#!/bin/bash
# Build a standalone device Release IPA. AltStore supplies the Apple signature.
# Usage: scripts/build-altstore.sh [OUTPUT_DIR]
#
# Preflights (docs/altstore.md): a clean working tree (the build is stamped
# with the git commit it came from), tests and typecheck. ios/ is generated by
# `expo prebuild` from app.json, so it is regenerated here rather than trusted.
set -euo pipefail
cd "$(dirname "$0")/.."

fail() {
  echo "build-altstore: $*" >&2
  exit 1
}

# --- Provenance: the IPA must be exactly one commit, so its SHA says what
# shipped. Tracked changes, and untracked files where the build reads source,
# both count.
build_inputs=(src assets app.json package.json package-lock.json tsconfig.json .env.production)
if ! git diff --quiet HEAD -- ||
  [[ -n "$(git ls-files --others --exclude-standard -- "${build_inputs[@]}")" ]]; then
  git status --short -- "${build_inputs[@]}" >&2 || true
  fail "the working tree has uncommitted changes; commit (or stash) them so the build maps to one git commit."
fi
git_sha="$(git rev-parse HEAD)"

# --- Preflights (no signing here: AltStore signs on the phone). Both take
# seconds, so unlike navsafe they run on every build.
npm test --silent >/dev/null 2>&1 || fail "tests failed: npm test"
npm run -s typecheck >/dev/null || fail "typecheck failed: npm run typecheck"

# --- Production config only. @expo/env lets .env.local (the dev deployment)
# override .env.production, so dotenv loading is switched off and the
# production values are exported instead; package-altstore.py then checks the
# bundle carries the production Convex URL and no other.
set -a
# shellcheck source=/dev/null
source .env.production
set +a
export EXPO_NO_DOTENV=1
[[ "$EXPO_PUBLIC_CONVEX_URL" =~ ^https://[a-z0-9-]+\.convex\.cloud$ ]] ||
  fail ".env.production has no EXPO_PUBLIC_CONVEX_URL"

output_dir="${1:-output/altstore-$(date -u +%Y-%m-%d-%H%M%S)}"
# UTC, like navsafe, so every build number is new and sorts by time.
build_number="${HOMEMOT_BUILD_NUMBER:-$(date -u +%Y%m%d%H)}"
mkdir -p "$output_dir"
output_dir="$(cd "$output_dir" && pwd)"
archive="$output_dir/HomeMOT.xcarchive"
ipa="$output_dir/HomeMOT-AltStore.ipa"
if [[ -e "$archive" || -e "$ipa" ]]; then
  fail "choose a new output directory; existing artifacts are preserved."
fi

echo "Regenerating ios/ from app.json…"
# CocoaPods crashes under a non-UTF-8 locale.
LANG=en_US.UTF-8 LC_ALL=en_US.UTF-8 CI=1 npx expo prebuild --platform ios \
  > "$output_dir/prebuild.log" 2>&1 ||
  fail "expo prebuild failed; see $output_dir/prebuild.log"
git diff --quiet HEAD -- ||
  fail "expo prebuild changed tracked files; commit them and build again."
# Prebuild writes app.json's ios.buildNumber (default 1) literally.
/usr/libexec/PlistBuddy -c "Set :CFBundleVersion $build_number" ios/HomeMOT/Info.plist

echo "Archiving Home MOT (AltStore) build $build_number from ${git_sha:0:12}…"
xcodebuild \
  -workspace ios/HomeMOT.xcworkspace \
  -scheme HomeMOT \
  -configuration Release \
  -destination 'generic/platform=iOS' \
  -derivedDataPath ios/build-altstore \
  -archivePath "$archive" \
  CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO \
  "CURRENT_PROJECT_VERSION=$build_number" archive \
  > "$output_dir/device-build.log" 2>&1 ||
  fail "archive failed; see $output_dir/device-build.log"

HOMEMOT_GIT_SHA="$git_sha" python3 scripts/package-altstore.py "$archive" "$ipa"
echo "Import $ipa in AltStore Classic, or publish it with scripts/publish-altstore.sh."
echo "Packaging checks do not replace simulator and iPhone acceptance testing."
